    CONSTRAINT ux_pedido_transferencia_envio_detalle UNIQUE (id_envio, id_pedido_detalle),
    CONSTRAINT pedido_transferencia_envio_detalle_cantidad_aceptada_check CHECK (cantidad_aceptada > 0::numeric),
    CONSTRAINT pedido_transferencia_envio_detalle_cantidad_enviada_check CHECK (cantidad_enviada > 0::numeric)
)

TABLESPACE pg_default;

ALTER TABLE IF EXISTS public.pedido_transferencia_envio_detalle
    OWNER to landiadm;
CREATE INDEX IF NOT EXISTS ix_pedido_transferencia_envio_detalle_producto
    ON public.pedido_transferencia_envio_detalle USING btree
    (id_empresa ASC NULLS LAST, id_producto ASC NULLS LAST, fecha_registro DESC NULLS FIRST)
    TABLESPACE pg_default;
CREATE TABLE IF NOT EXISTS public.pedido_transferencia_envios
(
    id_envio bigint NOT NULL DEFAULT nextval('pedido_transferencia_envios_id_envio_seq'::regclass),
    id_empresa integer NOT NULL,
    id_pedido bigint NOT NULL,
    id_sucursal_origen integer NOT NULL,
    id_sucursal_destino integer NOT NULL,
    id_usuario integer NOT NULL,
    idempotency_key character varying(80) COLLATE pg_catalog."default" NOT NULL,
    estatus character varying(20) COLLATE pg_catalog."default" NOT NULL DEFAULT 'CONFIRMADO'::character varying,
    total_productos integer NOT NULL DEFAULT 0,
    cantidad_total numeric(14,3) NOT NULL DEFAULT 0,
    fecha_confirmacion timestamp with time zone NOT NULL DEFAULT now(),
    CONSTRAINT pedido_transferencia_envios_pkey PRIMARY KEY (id_envio),
    CONSTRAINT ux_pedido_transferencia_envio_idempotencia UNIQUE (id_empresa, idempotency_key),
    CONSTRAINT ux_pedido_transferencia_envio_pedido UNIQUE (id_empresa, id_pedido),
    CONSTRAINT pedido_transferencia_envios_cantidad_total_check CHECK (cantidad_total >= 0::numeric),
    CONSTRAINT pedido_transferencia_envios_estatus_check CHECK (estatus::text = ANY (ARRAY['CONFIRMADO'::character varying, 'CANCELADO'::character varying]::text[])),
    CONSTRAINT pedido_transferencia_envios_total_productos_check CHECK (total_productos >= 0)
)

TABLESPACE pg_default;

ALTER TABLE IF EXISTS public.pedido_transferencia_envios
    OWNER to landiadm;
CREATE INDEX IF NOT EXISTS ix_pedido_transferencia_envios_empresa_fecha
    ON public.pedido_transferencia_envios USING btree
    (id_empresa ASC NULLS LAST, fecha_confirmacion DESC NULLS FIRST)
    TABLESPACE pg_default;
CREATE TABLE IF NOT EXISTS public.produccion_batida_firmas
(
    id bigint NOT NULL DEFAULT nextval('produccion_batida_firmas_id_seq'::regclass),
    id_orden bigint NOT NULL,
    tipo character varying(20) COLLATE pg_catalog."default" NOT NULL,
    id_usuario integer NOT NULL,
    firma_digital text COLLATE pg_catalog."default" NOT NULL,
    firma_hash text COLLATE pg_catalog."default" NOT NULL,
    fecha_firma timestamp with time zone NOT NULL DEFAULT now(),
    nombre_firmante character varying(120) COLLATE pg_catalog."default" NOT NULL,
    CONSTRAINT produccion_batida_firmas_pkey PRIMARY KEY (id),
    CONSTRAINT produccion_batida_firmas_firma_hash_key UNIQUE (firma_hash),
    CONSTRAINT produccion_batida_firmas_id_orden_tipo_key UNIQUE (id_orden, tipo),
    CONSTRAINT produccion_batida_firmas_tipo_check CHECK (tipo::text = ANY (ARRAY['CARNICERO'::character varying, 'ENCARGADO'::character varying]::text[]))
)

TABLESPACE pg_default;

ALTER TABLE IF EXISTS public.produccion_batida_firmas
    OWNER to landiadm;
CREATE INDEX IF NOT EXISTS ix_pbf_orden
    ON public.produccion_batida_firmas USING btree
    (id_orden ASC NULLS LAST)
    TABLESPACE pg_default;
CREATE UNIQUE INDEX IF NOT EXISTS ux_pbf_orden_nombre
    ON public.produccion_batida_firmas USING btree
    (id_orden ASC NULLS LAST, lower(btrim(nombre_firmante::text)) COLLATE pg_catalog."default" ASC NULLS LAST)
    TABLESPACE pg_default;
CREATE TABLE IF NOT EXISTS public.produccion_batida_pesajes
(
    id bigint NOT NULL DEFAULT nextval('produccion_batida_pesajes_id_seq'::regclass),
    id_orden bigint NOT NULL,
    kg numeric(12,3) NOT NULL,
    metodo_pesaje character varying(10) COLLATE pg_catalog."default" NOT NULL,
    bascula_id character varying(100) COLLATE pg_catalog."default",
    bascula_nombre character varying(200) COLLATE pg_catalog."default",
    id_gerente_autoriza integer,
    id_usuario integer NOT NULL,
    clave_idempotencia uuid NOT NULL,
    fecha_pesaje timestamp with time zone NOT NULL DEFAULT now(),
    enable boolean NOT NULL DEFAULT true,
    fecha_baja timestamp with time zone,
    id_usuario_baja integer,
    CONSTRAINT produccion_batida_pesajes_pkey PRIMARY KEY (id),
    CONSTRAINT produccion_batida_pesajes_id_orden_clave_idempotencia_key UNIQUE (id_orden, clave_idempotencia),
    CONSTRAINT produccion_batida_pesajes_check CHECK ((metodo_pesaje::text = 'MANUAL'::text) = (id_gerente_autoriza IS NOT NULL)),
    CONSTRAINT produccion_batida_pesajes_kg_check CHECK (kg > 0::numeric),
    CONSTRAINT produccion_batida_pesajes_metodo_pesaje_check CHECK (metodo_pesaje::text = ANY (ARRAY['BASCULA'::character varying, 'MANUAL'::character varying]::text[]))
)

TABLESPACE pg_default;

ALTER TABLE IF EXISTS public.produccion_batida_pesajes
    OWNER to landiadm;
CREATE INDEX IF NOT EXISTS ix_pbp_orden
    ON public.produccion_batida_pesajes USING btree
    (id_orden ASC NULLS LAST, fecha_pesaje ASC NULLS LAST, id ASC NULLS LAST)
    TABLESPACE pg_default
    WHERE enable;

 END;